import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];

  // Load ceramic-grain texture
  const texture = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');

  // Create plane geometry with 512:320 aspect ratio (1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Create material with ceramic texture
  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
    transparent: true
  });

  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  // Render text headline using fontAtlas
  if (ctx.fontAtlas) {
    const textData = config.textContent?.[0] || { text: 'Features 3' };
    const textMesh = ctx.fontAtlas({
      text: textData.text || 'Features 3',
      fontSize: 0.34, // headline em-height from design scale
      fontFamily: 'Lora',
      fontWeight: 400,
      color: 0xe8ecf2, // paper color for high contrast
      anchorX: 'center',
      anchorY: 'middle'
    });

    if (textMesh) {
      textMesh.position.z = 0.05; // Offset in front of plane
      group.add(textMesh);
    }
  }

  // Cleanup and resource disposal
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture?.dispose?.();
    timelines.forEach(tl => tl?.kill?.());
  };

  // Event handlers (static card, non-interactive)
  group.userData.handlers = {};

  return group;
}
